"""
The pinning law and the two refutations, quantitatively.

For the equal-volume peeling r_k = R (1 - k/N)^{1/d} of B(0,R) with thickness budget
delta, let T(N) be the number of shells thicker than delta.  This script measures:

  * how tightly the two-sided decay law
        j^{d-1} N < (R/(d delta))^d < (j+1)^{d-1} N   ==>   T in {j, j+1}
    pins the count, across a wide sweep of (d, N, delta);
  * the exact maximum of T over N, against the uniform bound 1 + R/(d delta) and
    against the (false) conjectured order d log(R/delta);
  * the exact thin-shell threshold, against the (false) conjectured (1-delta/R)^{-d}.
"""

from __future__ import annotations

import math
from typing import Dict, List, Tuple


def thickness_by_depth(R: float, d: int, N: int, j: int) -> float:
    """Thickness of the shell of inner depth j: R N^{-1/d} (j^{1/d} - (j-1)^{1/d})."""
    return R * N ** (-1.0 / d) * (j ** (1.0 / d) - (j - 1) ** (1.0 / d))


def thick_count(R: float, d: int, N: int, delta: float) -> int:
    """Exact thick-shell count, exploiting that the thick shells form a terminal block."""
    count = 0
    for j in range(1, N + 1):
        if thickness_by_depth(R, d, N, j) > delta:
            count = j
        else:
            break
    return count


def pinning_window(R: float, d: int, N: int, delta: float) -> Tuple[int, int]:
    """The window {j, j+1} predicted by the two-sided decay law."""
    cap = (R / (d * delta)) ** d
    if d == 1:
        return (N, N) if N < cap else (0, 0)
    j = 1
    while (j + 1) ** (d - 1) * N < cap:
        j += 1
    return j, j + 1


def sweep_pinning(R: float = 1.0) -> None:
    print("\n=== Pinning law: is T always inside its predicted window? ===")
    hits: Dict[str, int] = {"inside": 0, "outside": 0}
    worst: List[Tuple[int, int, float, int, Tuple[int, int]]] = []
    for d in (2, 3, 4, 6, 10):
        for delta in (0.2, 0.05, 0.02, 0.005):
            for N in (10, 30, 100, 300, 1000, 3000):
                m = thick_count(R, d, N, delta)
                lo, hi = pinning_window(R, d, N, delta)
                if m == 0 or m == N:
                    continue  # degenerate ends, outside the hypotheses of the law
                if lo <= m <= hi:
                    hits["inside"] += 1
                else:
                    hits["outside"] += 1
                    worst.append((d, N, delta, m, (lo, hi)))
    print(f"    non-degenerate cases inside the window: {hits['inside']}")
    print(f"    outside the window:                     {hits['outside']}")
    for w in worst[:10]:
        print("      violation:", w)


def sweep_maximum(R: float = 1.0) -> None:
    print("\n=== Worst-case count over N versus the uniform bound and the conjecture ===")
    print("      d   delta    max_N T   1 + R/(d delta)   d ln(R/delta)")
    for d in (1, 2, 3, 5, 10, 20):
        for delta in (0.05, 0.01):
            best = max(thick_count(R, d, N, delta) for N in range(1, 2000))
            print(f"   {d:4d} {delta:7.3f} {best:10d} {1 + R/(d*delta):17.2f}"
                  f" {d*math.log(R/delta):15.2f}")


def sweep_threshold(R: float = 1.0) -> None:
    print("\n=== Thin-shell threshold: (R/delta)^d, not (1 - delta/R)^{-d} ===")
    print("      d   delta   least N   (R/delta)^d   (1-delta/R)^{-d}")
    for d in (2, 3, 4, 5):
        for delta in (0.5, 0.25):
            least = next(N for N in range(1, 100000)
                         if thickness_by_depth(R, d, N, 1) <= delta + 1e-12)
            print(f"   {d:4d} {delta:7.3f} {least:9d} {(R/delta)**d:13.2f}"
                  f" {(1 - delta/R) ** (-d):18.2f}")


def main() -> None:
    print("=" * 74)
    print("Pinning, sharpness and refutations for equal-volume peelings")
    print("=" * 74)
    sweep_pinning()
    sweep_maximum()
    sweep_threshold()


if __name__ == "__main__":
    main()

